    self, vars_to_load: Optional[Sequence[VarData]] = None, solution_id=0
) -> Mapping[VarData, float]:
    if self._solver_model.SolCount == 0:
        raise NoSolutionError()
    attr = "X" if solution_id == 0 else "Xn"
    pvars, vals = self._get_var_values(attr, vars_to_load, solution_id)
    return ComponentMap(zip(pvars, vals))

